/**
 * Regenerates `src/generated/*` — the WASM rasterizer and the shared TTF, as
 * base64 string literals.
 *
 * They are embedded (rather than fetched or read from disk) so the renderer has
 * its rasterizer and its font from the very first frame, with no network, no
 * bundler asset plumbing and no toolchain: the generated files are committed,
 * so `build`, `typecheck` and `test` never need emscripten.
 *
 * Run through `native/build.sh`, which builds the WASM first.
 */

import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, "..");
const repo = join(pkg, "..", "..");
const generated = join(pkg, "src", "generated");

const WASM = join(pkg, "native", "stbtt.wasm");
const FONT = join(repo, "assets", "fonts", "LiberationSans-Regular.ttf");

mkdirSync(generated, { recursive: true });

emit({
  source: WASM,
  file: "stbtt-wasm.ts",
  constant: "STBTT_WASM_BASE64",
  header: `/**
 * stb_truetype compiled to standalone WASM — see native/stbtt.c and
 * native/build.sh. Base64 so it travels inside the JS bundle.
 */`,
});

emit({
  source: FONT,
  file: "font.ts",
  constant: "DEFAULT_FONT_BASE64",
  extra: [
    "/** The font's file name — the same file every target ships (see assets/fonts/). */",
    'export const DEFAULT_FONT_NAME = "LiberationSans-Regular.ttf";',
  ],
  header: `/**
 * Liberation Sans Regular (SIL OFL 1.1 — see assets/fonts/), the shared TTF
 * every zabloo target rasterizes. Metric-compatible with Arial, which is what
 * the Canvas2D fallback and Unity's legacy font used before ZAB-43.
 */`,
});

/**
 * Writes one generated module. The payload is a single string literal on one
 * line: splitting it into concatenated chunks would leave the parser thousands
 * of binary expressions to fold. `src/generated` is excluded from biome for
 * exactly this reason.
 */
function emit({ source, file, constant, header, extra = [] }) {
  const bytes = readFileSync(source);
  const base64 = bytes.toString("base64");
  const sha256 = createHash("sha256").update(bytes).digest("hex");

  const lines = [
    "// GENERATED by scripts/embed-binaries.mjs — do not edit by hand.",
    `// source: ${source.slice(repo.length + 1)} (${bytes.length} bytes, sha256 ${sha256})`,
    "",
    header,
    `export const ${constant} = "${base64}";`,
  ];
  if (extra.length > 0) lines.push("", ...extra);

  writeFileSync(join(generated, file), `${lines.join("\n")}\n`);
  console.log(`wrote src/generated/${file} (${bytes.length} bytes → ${base64.length} base64)`);
}
